import{_ as t,c as a,o as s,a3 as o}from"./chunks/framework.BNw1pucY.js";const g=JSON.parse('{"title":"CLI","description":"Look up Agent SDK commands, targets, flags, outputs, and exit status.","frontmatter":{"title":"CLI","description":"Look up Agent SDK commands, targets, flags, outputs, and exit status."},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),n={name:"reference/cli.md"};function d(c,e,l,i,r,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="agent-sdk-cli" tabindex="-1">Agent SDK CLI <a class="header-anchor" href="#agent-sdk-cli" aria-label="Permalink to &quot;Agent SDK CLI&quot;">​</a></h1><p>The CLI needs Node 22.13 or newer. Run <code>agent-sdk &lt;command&gt; --help</code> to see every flag for that command.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk &lt;command&gt;</span></span></code></pre></div><p><code>agent-sdk help --all</code> prints every command, and <code>agent-sdk help &lt;command&gt; --json</code> prints one command&#39;s flags as JSON.</p><p>Commands are named <code>agent-sdk &lt;resource&gt; &lt;verb&gt;</code>, such as <code>agent-sdk deployment list</code>, apart from workflow verbs such as <code>init</code>, <code>dev</code>, and <code>deploy</code>. Older names, such as <code>agent-sdk deployments</code> or <code>agent-sdk secrets set</code>, still run and print the new form on stderr. The <code>bdk</code> command remains available.</p><h2 id="command-catalog" tabindex="-1">Command catalog <a class="header-anchor" href="#command-catalog" aria-label="Permalink to &quot;Command catalog&quot;">​</a></h2><h3 id="development-commands" tabindex="-1">Development commands <a class="header-anchor" href="#development-commands" aria-label="Permalink to &quot;Development commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Contract</th></tr></thead><tbody><tr><td><code>help</code>, <code>--help</code>, <code>-h</code></td><td>Print the command index, or one command&#39;s help</td></tr><tr><td><a href="#serve"><code>serve</code></a></td><td>Serve one or more agents over HTTP</td></tr><tr><td><a href="#dev"><code>dev</code></a></td><td>Serve agents with local-development behavior</td></tr><tr><td><a href="#docs"><code>docs</code></a></td><td>Serve the bundled documentation</td></tr><tr><td><a href="#init"><code>init</code></a></td><td>Scaffold a project, or convert an Automation</td></tr><tr><td><a href="#migrate"><code>migrate</code></a></td><td>Open a pull request that migrates an early-alpha project</td></tr><tr><td><a href="#skills-install"><code>skills list</code>, <code>skills install</code></a></td><td>List or refresh the bundled coding-agent skills</td></tr><tr><td><a href="#info"><code>info</code></a></td><td>Print a project&#39;s discovered parts or deployment manifest</td></tr><tr><td><a href="#validate"><code>validate</code></a></td><td>Check project diagnostics and set the exit status</td></tr><tr><td><a href="#version"><code>version</code></a></td><td>Print the installed package version</td></tr><tr><td><a href="#update"><code>update</code></a></td><td>Upgrade the installed CLI</td></tr><tr><td><a href="#login-logout-whoami"><code>login</code>, <code>logout</code>, <code>whoami</code></a></td><td>Store, remove, or show the Cursor credential</td></tr></tbody></table><h3 id="session-and-eval-commands" tabindex="-1">Session and eval commands <a class="header-anchor" href="#session-and-eval-commands" aria-label="Permalink to &quot;Session and eval commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Contract</th></tr></thead><tbody><tr><td><a href="#chat"><code>chat</code></a></td><td>Talk to a running agent, or reattach a session</td></tr><tr><td><a href="#run"><code>run</code></a></td><td>Run turns on a local or running agent</td></tr><tr><td><a href="#tool-call"><code>tool call</code></a></td><td>Call a server tool without a model turn</td></tr><tr><td><a href="#logs"><code>logs</code></a></td><td>Follow or dump agent logs</td></tr><tr><td><a href="#session-list"><code>session list</code></a></td><td>List sessions, or their costs</td></tr><tr><td><a href="#session-get"><code>session get</code></a></td><td>Inspect a session or a saved trace</td></tr><tr><td><a href="#session-create"><code>session create</code></a></td><td>Start or continue a hosted session</td></tr><tr><td><a href="#eval"><code>eval</code></a></td><td>Run evals, or list, get, and cancel remote eval batches</td></tr></tbody></table><h3 id="managed-hosting-commands" tabindex="-1">Managed hosting commands <a class="header-anchor" href="#managed-hosting-commands" aria-label="Permalink to &quot;Managed hosting commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Contract</th></tr></thead><tbody><tr><td><a href="#deploy"><code>deploy</code></a></td><td>Deploy an agent</td></tr><tr><td><a href="#deployment-list"><code>deployment list</code>, <code>deployment get</code></a></td><td>List deployments, or inspect one</td></tr><tr><td><a href="#deployment-lifecycle"><code>deployment stop</code>, <code>start</code>, <code>kill</code>, <code>unlock</code>, <code>cancel-runs</code>, <code>upgrade</code>, <code>rollback</code>, <code>delete</code>, <code>rotate-token</code></a></td><td>Change a deployment&#39;s state, release, or alias token</td></tr><tr><td><a href="#deployment-update"><code>deployment update</code></a></td><td>Replace a deployment&#39;s event repositories</td></tr><tr><td><a href="#secret"><code>secret</code></a></td><td>Set, list, or delete deployment secrets</td></tr></tbody></table><h3 id="connection-and-channel-commands" tabindex="-1">Connection and channel commands <a class="header-anchor" href="#connection-and-channel-commands" aria-label="Permalink to &quot;Connection and channel commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Contract</th></tr></thead><tbody><tr><td><a href="#mcp"><code>mcp serve</code>, <code>mcp install</code></a></td><td>Connect an MCP client to an agent</td></tr><tr><td><a href="#mcp-oauth"><code>mcp oauth</code></a></td><td>Authorize an MCP connection</td></tr><tr><td><a href="#slack"><code>slack</code></a></td><td>Provision and check Slack channel apps</td></tr><tr><td><a href="#github"><code>github</code></a></td><td>Forward, replay, and inspect GitHub webhooks</td></tr><tr><td><a href="#replay-other-webhooks"><code>gitlab</code>, <code>bitbucket</code>, <code>pagerduty</code></a></td><td>Replay and inspect GitLab, Bitbucket, or PagerDuty webhooks</td></tr></tbody></table><h2 id="choose-a-target" tabindex="-1">Targets <a class="header-anchor" href="#choose-a-target" aria-label="Permalink to &quot;Targets {#choose-a-target}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>Selection</th><th>Commands</th></tr></thead><tbody><tr><td>Ephemeral local server</td><td>Omit <code>--url</code> and <code>--prod</code></td><td><code>run</code>, <code>tool call</code>, <code>eval</code></td></tr><tr><td>Running server</td><td>Pass <code>--url &lt;baseUrl&gt;</code></td><td><code>chat</code>, <code>run</code>, <code>tool call</code>, <code>eval</code>, <code>logs</code>, <code>session list</code>, <code>session get</code>, <code>mcp serve</code></td></tr><tr><td>Default local server</td><td>Omit <code>--url</code> and <code>--prod</code> to use <code>http://127.0.0.1:3000</code></td><td><code>chat</code>, <code>logs</code>, <code>session list</code>, <code>session get</code></td></tr><tr><td>Hosted deployment</td><td>Pass <code>--prod</code></td><td><code>session list</code>, <code>session get</code>, <code>logs</code>. <code>session create</code> is always hosted.</td></tr></tbody></table><p>A hosted deployment supports only the commands in its row. <code>chat</code>, <code>run</code>, <code>tool call</code>, <code>eval</code>, <code>mcp serve</code>, and <code>mcp install</code> exit with a usage error when you pass <code>--prod</code>. To test a hosted agent, start a turn with <a href="#session-create"><code>session create</code></a> and inspect it with <a href="#session-get"><code>session get</code></a>.</p><p><code>--url</code> and <code>--prod</code> are mutually exclusive. An explicit <code>--url</code> must include the slug for a multi-agent server, such as <code>http://127.0.0.1:3000/pr-approver</code>. Otherwise <code>--slug</code> picks the agent, and under <code>--prod</code> it defaults to the <code>--dir</code> basename. <code>--json</code> prints one JSON document on stdout, including errors. Without it, output is text, even when piped.</p><h2 id="local-servers" tabindex="-1">Local servers <a class="header-anchor" href="#local-servers" aria-label="Permalink to &quot;Local servers&quot;">​</a></h2><h3 id="serve" tabindex="-1">Serve agents <a class="header-anchor" href="#serve" aria-label="Permalink to &quot;Serve agents {#serve}&quot;">​</a></h3><p><code>serve</code> mounts every project discovered under <code>--dir</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk serve [--dir &lt;path&gt;] [--port &lt;n&gt;] [--host &lt;host&gt;]</span></span>
<span class="line"><span>  [--mode multi|single] [--dev] [--api-key &lt;key&gt;]</span></span>
<span class="line"><span>  [--state-root &lt;path&gt;]</span></span>
<span class="line"><span>  [--bearer-token &lt;secret&gt; | --allow-anonymous]</span></span>
<span class="line"><span>  [--allow-anonymous-cursor-github]</span></span>
<span class="line"><span>  [--allow-anonymous-cursor-account-mcp]</span></span>
<span class="line"><span>  [--public-url &lt;url&gt;]</span></span>
<span class="line"><span>  [--peers-url &lt;url&gt;]</span></span>
<span class="line"><span>  [--no-schedules] [--no-playground] [--no-docs]</span></span>
<span class="line"><span>  [--cursor-events --repo &lt;owner/name&gt;]...</span></span></code></pre></div><p><code>serve</code> listens on <code>127.0.0.1:3000</code>, or the next free port when that one is taken. <code>--mode multi</code>, the default, mounts each project at <code>/&lt;slug&gt;/v1/*</code>, and <code>--mode single</code> mounts one project at <code>/v1/*</code>. <code>--dev</code> turns off schedule and reminder firing and admits unsigned loopback GitHub deliveries.</p><p><code>--bearer-token</code> requires a token on routes that don&#39;t declare their own authentication. <code>--allow-anonymous</code> admits every caller as one principal, so use it only behind a trusted network boundary. The slugs <code>v1</code>, <code>playground</code>, and <code>docs</code> are reserved.</p><h3 id="dev" tabindex="-1">Develop locally <a class="header-anchor" href="#dev" aria-label="Permalink to &quot;Develop locally {#dev}&quot;">​</a></h3><p><code>dev</code> is <code>serve --dev</code> with an optional project path:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk dev</span></span>
<span class="line"><span>agent-sdk dev ./agent-sdk-pr-reviewer --port 3000</span></span></code></pre></div><p>It accepts every <code>serve</code> option. Don&#39;t combine the path with a different <code>--dir</code>.</p><h3 id="docs" tabindex="-1">Serve the docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Serve the docs {#docs}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk docs [--port &lt;n&gt;] [--host 127.0.0.1] [--print]</span></span></code></pre></div><p><code>docs</code> serves the bundled documentation on a loopback port until you press Ctrl-C. <code>--print</code> prints the URL without opening a browser.</p><h2 id="sessions-and-turns" tabindex="-1">Sessions and turns <a class="header-anchor" href="#sessions-and-turns" aria-label="Permalink to &quot;Sessions and turns&quot;">​</a></h2><h3 id="chat" tabindex="-1">Chat with an agent <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat with an agent {#chat}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk chat [--url &lt;baseUrl&gt;] [--message &lt;text&gt;]</span></span>
<span class="line"><span>  [--session &lt;id&gt; | --resume] [--continuation-token &lt;token&gt;]</span></span>
<span class="line"><span>  [--slug &lt;slug&gt;] [--json] [--text] [--no-color]</span></span></code></pre></div><p>On a TTY, <code>chat</code> opens a REPL and sends any <code>--message</code> first. Without a TTY, it sends <code>--message</code> as one turn, or reads newline-delimited messages until EOF. <code>--session &lt;id&gt;</code> reattaches a stored session, and <code>--resume</code> picks the most recent one.</p><h3 id="run" tabindex="-1">Run turns <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run turns {#run}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk run [--dir &lt;path&gt;] [--message &lt;text&gt;]...</span></span>
<span class="line"><span>  [--messages-file &lt;path&gt;] [--url &lt;baseUrl&gt;]</span></span>
<span class="line"><span>  [--session &lt;id&gt;] [--continuation-token &lt;token&gt;]</span></span>
<span class="line"><span>  [--trace &lt;file&gt; | --no-trace] [--json]</span></span>
<span class="line"><span>  [--timeout-ms &lt;n&gt;] [--no-stream] [--slug &lt;slug&gt;] [--dry-run]</span></span></code></pre></div><p>Repeat <code>--message</code> for a multi-turn run. <code>run</code> prints the compact trajectory, writes an NDJSON trace unless you pass <code>--no-trace</code>, and exits <code>1</code> when the trajectory fails. It has no default timeout.</p><h3 id="tool-call" tabindex="-1">Call a tool <a class="header-anchor" href="#tool-call" aria-label="Permalink to &quot;Call a tool {#tool-call}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk tool call &lt;tool&gt; [--input &lt;json&gt;]</span></span>
<span class="line"><span>  [--dir &lt;path&gt; | --url &lt;baseUrl&gt;]</span></span>
<span class="line"><span>  [--session &lt;id&gt;] [--slug &lt;slug&gt;] [--json]</span></span></code></pre></div><p><code>--input</code> takes JSON and defaults to <code>{}</code>. <code>--session</code> runs the tool in that session&#39;s workspace and records the call. The command exits <code>1</code> unless the response has <code>ok: true</code>. See <a href="./tools.html#call-a-tool-without-a-model-turn">Tools</a> for error codes.</p><h3 id="session-list" tabindex="-1">List sessions <a class="header-anchor" href="#session-list" aria-label="Permalink to &quot;List sessions {#session-list}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk session list [--url &lt;baseUrl&gt; | --prod] [--since &lt;duration|instant&gt;]</span></span>
<span class="line"><span>  [--view sessions|cost] [--slug &lt;slug&gt;] [--team &lt;id&gt;]</span></span>
<span class="line"><span>  [--bearer-token &lt;token&gt;] [--limit &lt;n&gt;] [--page-token &lt;token&gt;] [--json]</span></span></code></pre></div><p><code>--limit</code> sets the page size, 20 by default and at most 100. With <code>--prod</code>, it lists the most recently active hosted sessions, and <code>--since</code> reads back to a cutoff such as <code>24h</code> or an ISO-8601 instant. <code>--view cost</code> works only against a running server.</p><h3 id="session-get" tabindex="-1">Inspect a session <a class="header-anchor" href="#session-get" aria-label="Permalink to &quot;Inspect a session {#session-get}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk session get &lt;sessionId&gt; [--url &lt;baseUrl&gt; | --prod]</span></span>
<span class="line"><span>  [--slug &lt;slug&gt;] [--team &lt;id&gt;]</span></span>
<span class="line"><span>  [--view trajectory|events|cost] [--json [--fields &lt;a,b.c&gt;]]</span></span>
<span class="line"><span>  [--trace &lt;file.ndjson&gt;] [--web [--print]]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>agent-sdk session get --file &lt;file.ndjson&gt; [--json]</span></span></code></pre></div><p><code>session get</code> prints a compact trajectory, or raw <a href="./sessions.html#stream-events">events</a> with <code>--view events</code>. <code>--view cost</code> and <code>--trace</code> work only locally. <code>--file</code> reads a saved trace and exits <code>1</code> when that trajectory failed, and <code>--web</code> opens the session in the playground. For a hosted deployment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prod</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sessionI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slug</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events</span></span></code></pre></div><h3 id="session-create" tabindex="-1">Start a hosted session <a class="header-anchor" href="#session-create" aria-label="Permalink to &quot;Start a hosted session {#session-create}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk session create --message &lt;text&gt; [--session &lt;ses_...&gt;]</span></span>
<span class="line"><span>  [--slug &lt;slug&gt;] [--team &lt;id&gt;] [--wait [--timeout-ms &lt;n&gt;]]</span></span>
<span class="line"><span>  [--read-only] [--as-of &lt;instant&gt;] [--component &lt;key&gt;] [--dry-run] [--json]</span></span></code></pre></div><p><code>session create</code> sends one <code>--message</code> to the hosted deployment. Without <code>--wait</code>, it exits <code>0</code> once the deployment accepts the turn, before a new session has an ID. <code>--wait</code> polls until the session starts. It exits <code>3</code> when <code>--timeout-ms</code> passes first and <code>1</code> when the delivery is skipped or fails.</p><p><code>--session</code> continues a session that <code>session create</code> started. <code>--read-only</code> stubs write tools, and <code>--as-of</code> freezes the session&#39;s clock at an ISO-8601 instant. See <a href="./../deployment.html#verify-a-hosted-turn">Verify a hosted turn</a>.</p><h3 id="logs" tabindex="-1">Follow logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Follow logs {#logs}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk logs [sessionId] [--url &lt;baseUrl&gt; | --prod]</span></span>
<span class="line"><span>  [--session &lt;sessionId&gt;] [--slug &lt;slug&gt;] [--team &lt;id&gt;] [--once] [--json]</span></span></code></pre></div><p><code>logs</code> follows output until Ctrl-C, and <code>--once</code> prints the current buffer and exits. With <code>--prod</code>, it follows the hosted deployment&#39;s recent sessions and prints a <code>==&gt; &lt;sessionId&gt; (&lt;channel&gt;) &lt;==</code> header when the output switches sessions. A session ID follows one hosted session and requires <code>--prod</code>.</p><h2 id="evals" tabindex="-1">Evals <a class="header-anchor" href="#evals" aria-label="Permalink to &quot;Evals&quot;">​</a></h2><h3 id="eval" tabindex="-1">Run evals <a class="header-anchor" href="#eval" aria-label="Permalink to &quot;Run evals {#eval}&quot;">​</a></h3><p><code>eval</code> discovers <code>evals/**/*.eval.{ts,js}</code> and runs the selected cases:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk eval [--dir &lt;path&gt;] [evalId...]</span></span>
<span class="line"><span>  [--list] [--tag &lt;tag&gt;]... [--json] [--verbose]</span></span>
<span class="line"><span>  [--timeout-ms &lt;n&gt;] [--strict] [--max-concurrency &lt;n&gt;]</span></span>
<span class="line"><span>  [--junit &lt;path&gt;] [--artifacts &lt;dir&gt; | --no-artifacts]</span></span>
<span class="line"><span>  [--skip-report] [--no-stream]</span></span>
<span class="line"><span>  [--url &lt;baseUrl&gt;] [--no-wait] [--slug &lt;slug&gt;]</span></span></code></pre></div><p>Select an exact case such as <code>weather/nyc</code>, a file prefix such as <code>weather</code>, several IDs, or none for every case. Put an ID that is also a subcommand word after <code>--</code>, as in <code>agent-sdk eval -- list</code>. The project needs an <a href="./evals.html#eval-configuration">eval configuration</a>.</p><p><code>--strict</code> fails a scored case below its soft threshold. The command exits <code>1</code> for failed cases and <code>2</code> for invalid options or no matching cases. A running server prints an Eval ID when it accepts the batch, and <code>--no-wait</code> returns at that point. These commands require <code>--url</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk eval list --url &lt;baseUrl&gt; [--limit &lt;n&gt;] [--page-token &lt;token&gt;]</span></span>
<span class="line"><span>agent-sdk eval get &lt;evalId&gt; --url &lt;baseUrl&gt;</span></span>
<span class="line"><span>agent-sdk eval cancel &lt;evalId&gt; --url &lt;baseUrl&gt;</span></span></code></pre></div><p><code>eval get</code> exits <code>3</code> while the batch runs and <code>1</code> when it failed or was cancelled.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><h3 id="init" tabindex="-1">Scaffold a project <a class="header-anchor" href="#init" aria-label="Permalink to &quot;Scaffold a project {#init}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk init [directory] [--template &lt;name&gt;] [--var id=value]... [--json] [--dry-run]</span></span>
<span class="line"><span>agent-sdk init [directory] --from automation:&lt;url-or-uuid&gt; [--dry-run] [--json]</span></span></code></pre></div><p>Without a directory, <code>init</code> prints the setup guide. With one, it adds missing scaffold files, installs dependencies, and tries to put <code>agent-sdk</code> on <code>PATH</code>. On a TTY, it also asks the template&#39;s questions and starts login when needed.</p><p><code>--template</code> takes <code>agentic-owners</code>, <code>agents-md</code>, <code>code-wiki</code>, <code>demo</code>, <code>security-help</code>, <code>security-reviewer</code>, <code>thermo-quality-review</code>, <code>thermo-review</code>, <code>triage-jira</code>, or <code>triage-linear</code>. <code>triage</code> selects <code>triage-linear</code>. <code>--var id=value</code> answers a template question without a prompt. <code>--dry-run</code> lists the files without writing them.</p><h4 id="convert-automation" tabindex="-1">Convert an Automation <a class="header-anchor" href="#convert-automation" aria-label="Permalink to &quot;Convert an Automation {#convert-automation}&quot;">​</a></h4><p><code>--from automation:</code> takes a Cursor Automation dashboard URL or UUID and writes to <code>./&lt;automation-name&gt;</code> unless you name a directory. Generated files don&#39;t overwrite existing paths, but the <code>npm install</code> that follows can run lifecycle scripts from an existing <code>package.json</code>. See <a href="./../guides/convert-automation.html">Convert a Cursor Automation</a>.</p><h3 id="migrate" tabindex="-1">Migrate an early-alpha project <a class="header-anchor" href="#migrate" aria-label="Permalink to &quot;Migrate an early-alpha project {#migrate}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk migrate [--dir &lt;path&gt;] [--repo &lt;https-url&gt;] [--ref &lt;git-ref&gt;]</span></span>
<span class="line"><span>  [--path &lt;agent-path&gt;] [--no-wait] [--json] [--api-key &lt;key&gt;]</span></span></code></pre></div><p><code>migrate</code> applies only to projects that deployed with <code>architecture: &quot;v1&quot;</code> during the early alpha. It starts a Cursor cloud agent on a pushed Git ref with the bundled <code>bdk-migrate-v2</code> skill, and the agent opens a pull request with the source changes. The command never deploys or changes secrets.</p><p>With nothing to change, it prints <code>Nothing to migrate.</code> and exits <code>0</code>, and it exits <code>1</code> if the run ends without a pull request. <code>deploy</code> refuses a project that sets <code>architecture: &quot;v1&quot;</code> and points to <code>migrate</code>. See <a href="./../guides/migrate.html">Migrate an early-alpha project</a>.</p><h3 id="skills-install" tabindex="-1">Install and list coding-agent skills <a class="header-anchor" href="#skills-install" aria-label="Permalink to &quot;Install and list coding-agent skills {#skills-install}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk skills install [--dry-run] [--json]</span></span>
<span class="line"><span>agent-sdk skills list [--json [--fields &lt;a,b.c&gt;]] [--limit &lt;n&gt;] [--page-token &lt;token&gt;]</span></span></code></pre></div><p>Package installation copies the bundled skills, <code>skills install</code> replaces the installed copies and removes stale ones, and <code>skills list</code> prints each skill&#39;s bundled and installed versions. The <code>bdk-cli</code> skill teaches agents to run <code>agent-sdk</code> safely.</p><h3 id="info" tabindex="-1">Inspect a project <a class="header-anchor" href="#info" aria-label="Permalink to &quot;Inspect a project {#info}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk info [--dir &lt;path&gt;] [--view info|manifest] [--json [--fields &lt;a,b.c&gt;]]</span></span></code></pre></div><p>Text output lists what discovery found, such as tools, channels, and diagnostics. <code>--view manifest</code> summarizes one project&#39;s deployment metadata without a network request.</p><h3 id="validate" tabindex="-1">Validate a project <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;Validate a project {#validate}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk validate [--dir &lt;path&gt;]</span></span></code></pre></div><p><code>validate</code> prints every discovered project&#39;s diagnostics and exits <code>1</code> when any diagnostic has error severity. <code>validate</code> fails when an SCM webhook secret or GitHub credential is a literal or a getter, and the error message shows the <code>{ secretName }</code> form to use. A project that still sets <code>architecture: &quot;v1&quot;</code> gets the same finding as a warning.</p><h2 id="credentials-and-versions" tabindex="-1">Credentials and versions <a class="header-anchor" href="#credentials-and-versions" aria-label="Permalink to &quot;Credentials and versions&quot;">​</a></h2><h3 id="login-logout-whoami" tabindex="-1">Manage credentials <a class="header-anchor" href="#login-logout-whoami" aria-label="Permalink to &quot;Manage credentials {#login-logout-whoami}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk login [--api-key &lt;key&gt;] [--key-name &lt;name&gt;]</span></span>
<span class="line"><span>agent-sdk whoami [--json]</span></span>
<span class="line"><span>agent-sdk logout</span></span></code></pre></div><p><code>login</code> stores a supplied API key, or opens browser sign-in and stores the key it creates. <code>whoami</code> shows the active credential and its source. <code>logout</code> removes the stored credential but doesn&#39;t revoke the key, so revoke it in the Cursor dashboard.</p><h3 id="version" tabindex="-1">Print the version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Print the version {#version}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk version [--json]</span></span>
<span class="line"><span>agent-sdk --version</span></span></code></pre></div><h3 id="update" tabindex="-1">Update the CLI <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update the CLI {#update}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk update</span></span></code></pre></div><p><code>update</code> upgrades a recognized global or project install to npm&#39;s <code>latest</code> tag, or prints a manual upgrade command. Published installs check for updates daily unless an <a href="#environment-variables">update-check variable</a> is set.</p><h2 id="managed-hosting" tabindex="-1">Managed hosting <a class="header-anchor" href="#managed-hosting" aria-label="Permalink to &quot;Managed hosting&quot;">​</a></h2><p>Every command here that changes a deployment takes <code>--dry-run</code>, which runs the reads, stops at the first change, prints that request with secrets redacted, and exits <code>0</code>.</p><p><code>secret delete</code>, <code>image delete</code>, <code>slack destroy</code>, and the <code>deployment</code> commands marked No in the <a href="#deployment-lifecycle">lifecycle table</a> can&#39;t be undone. On a terminal they ask you to type the slug or name, and a mismatch exits <code>1</code>. Without a terminal, they exit <code>2</code> unless you pass <code>--yes</code>.</p><h3 id="deploy" tabindex="-1">Deploy agents <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy agents {#deploy}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk deploy [--dir &lt;path&gt;] [--slug &lt;slug&gt; | --all] [--team &lt;id&gt;]</span></span>
<span class="line"><span>  [--repo &lt;https-url&gt;] [--ref &lt;git-ref&gt;] [--path &lt;agent-path&gt;]</span></span>
<span class="line"><span>  [--cursor-events-repo &lt;repo&gt;]... [--no-wait] [--json]</span></span></code></pre></div><p>Deploying needs a team with agent hosting turned on, and a team service-account key with agent access can deploy. The CLI infers <code>--repo</code>, <code>--ref</code>, and <code>--path</code> from the current checkout, and the repository must use HTTPS.</p><p><code>deploy</code> deploys one agent. On a folder of several agents, pass <code>--slug</code> to pick one. <code>--all</code>, or picking several agents, prints one <code>agent-sdk deploy --dir</code> command per agent and exits <code>1</code>.</p><p><code>--cursor-events-repo</code> sets the repositories whose Cursor events the deployment receives. Write <code>owner/name</code> for GitHub, <code>gitlab.com/&lt;group&gt;/&lt;project&gt;</code> for GitLab, or <code>bitbucket.org/&lt;workspace&gt;/&lt;repo&gt;</code> for Bitbucket. A GitLab path can include subgroups. Repeat the flag once per repository. Each deploy replaces the whole list. Without the flag, the deployment watches its GitHub source repository.</p><p><code>deploy</code> waits until the deployment runs and exits nonzero if it fails, unless you pass <code>--no-wait</code>. The first deploy of a slug can print an alias token once. Slugs use lowercase letters, digits, <code>_</code>, and <code>-</code>, start with a letter or digit, and have at most 64 characters. See <a href="./../deployment.html">Deployment</a> for egress hosts and the alias token.</p><h3 id="deployment-list" tabindex="-1">Inspect deployments <a class="header-anchor" href="#deployment-list" aria-label="Permalink to &quot;Inspect deployments {#deployment-list}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk deployment list [--team &lt;id&gt;] [--limit &lt;n&gt;] [--page-token &lt;token&gt;]</span></span>
<span class="line"><span>  [--json [--fields &lt;a,b.c&gt;]]</span></span>
<span class="line"><span>agent-sdk deployment get &lt;slug&gt; [--team &lt;id&gt;] [--json [--fields &lt;a,b.c&gt;]] [--web]</span></span></code></pre></div><p><code>deployment list</code> shows each deployment&#39;s slug, status, and update time, and <code>deployment get</code> adds the release, watched repositories, routes, secret names, and latest error. <code>--web</code> opens the deployment in <a href="https://cursor.com/dashboard/deployed-agents" target="_blank" rel="noreferrer">Deployed Agents</a>, and an early-alpha deployment shows the steps to migrate it.</p><h3 id="deployment-lifecycle" tabindex="-1">Change a deployment <a class="header-anchor" href="#deployment-lifecycle" aria-label="Permalink to &quot;Change a deployment {#deployment-lifecycle}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk deployment &lt;command&gt; &lt;slug&gt; [--team &lt;id&gt;] [--json] [--dry-run]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th><th>Undoable?</th></tr></thead><tbody><tr><td><code>stop</code></td><td>Stop the deployment. <code>--cancel-runs</code> also cancels active runs and reminder wakes.</td><td>Yes</td></tr><tr><td><code>start</code></td><td>Resume a stopped deployment. A kill lock stays.</td><td>Yes</td></tr><tr><td><code>kill</code></td><td>Lock deploys, stop the deployment, and cancel its runs and reminder wakes. To recover, run <code>unlock</code> and then <code>start</code>.</td><td>No</td></tr><tr><td><code>unlock</code></td><td>Remove the kill lock so deploys, upgrades, and rollbacks work again. Traffic stays stopped.</td><td>Yes</td></tr><tr><td><code>cancel-runs</code></td><td>Cancel active runs and reminder wakes.</td><td>No</td></tr><tr><td><code>update</code></td><td>Replace the <a href="#deployment-update">event repositories</a>.</td><td>Yes</td></tr><tr><td><code>upgrade</code></td><td>Move to a ready release, the newest unless you pass <code>--release</code>.</td><td>Yes</td></tr><tr><td><code>rollback</code></td><td>Move to an earlier ready release, the previous one unless you pass <code>--release</code>.</td><td>Yes</td></tr><tr><td><code>delete</code></td><td>Remove the deployment and free its slug.</td><td>No</td></tr><tr><td><code>rotate-token</code></td><td>Replace the alias token. The old one stops working at once.</td><td>No</td></tr></tbody></table><h3 id="deployment-update" tabindex="-1">Replace event repositories <a class="header-anchor" href="#deployment-update" aria-label="Permalink to &quot;Replace event repositories {#deployment-update}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk deployment update &lt;slug&gt; (--event-repo &lt;owner/name&gt;... | --no-event-repos)</span></span>
<span class="line"><span>  [--team &lt;id&gt;] [--dry-run] [--json]</span></span></code></pre></div><p>The repositories you pass replace the deployment&#39;s whole event repository list, and <code>--no-event-repos</code> clears it.</p><h3 id="secret" tabindex="-1">Manage deployment secrets <a class="header-anchor" href="#secret" aria-label="Permalink to &quot;Manage deployment secrets {#secret}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk secret set &lt;slug&gt; NAME [NAME2 ...]</span></span>
<span class="line"><span>  [--team &lt;id&gt;] [--from-argv] [--json]</span></span>
<span class="line"><span>agent-sdk secret list &lt;slug&gt; [--team &lt;id&gt;] [--limit &lt;n&gt;] [--page-token &lt;token&gt;] [--json]</span></span>
<span class="line"><span>agent-sdk secret delete &lt;slug&gt; NAME [--team &lt;id&gt;] [--yes] [--dry-run] [--json]</span></span></code></pre></div><p>On a TTY, <code>secret set</code> prompts for each hidden value. With one name, redirected stdin is the whole value minus one trailing newline, so a PEM key keeps its line breaks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-bot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GITHUB_APP_PRIVATE_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./app.private-key.pem</span></span></code></pre></div><p>With several names, give one line per name. <code>set</code> rejects <code>NAME=VALUE</code> arguments unless you pass <code>--from-argv</code>, because shell history keeps them. Names use <code>UPPER_SNAKE_CASE</code>, and the <code>CURSOR_</code> prefix is reserved. <code>secret list</code> returns names, never values.</p><h2 id="mcp-connections" tabindex="-1">MCP connections <a class="header-anchor" href="#mcp-connections" aria-label="Permalink to &quot;MCP connections&quot;">​</a></h2><h3 id="mcp" tabindex="-1">Connect an MCP client <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;Connect an MCP client {#mcp}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk mcp serve --url &lt;baseUrl&gt; [--bearer-token &lt;token&gt;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>agent-sdk mcp install --url &lt;baseUrl&gt; [--bearer-token &lt;token&gt;]</span></span>
<span class="line"><span>  [--name &lt;server-name&gt;] [--dry-run] [--json]</span></span></code></pre></div><p><code>mcp serve</code> proxies newline-delimited JSON-RPC from stdin to the agent&#39;s MCP endpoint and reserves stdout for MCP messages. <code>mcp install</code> adds the agent to <code>~/.cursor/mcp.json</code>. An entry made with <code>--bearer-token</code> contains that token, so treat every printed or written copy as a credential.</p><h3 id="mcp-oauth" tabindex="-1">Authorize MCP OAuth <a class="header-anchor" href="#mcp-oauth" aria-label="Permalink to &quot;Authorize MCP OAuth {#mcp-oauth}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk mcp oauth &lt;connection&gt; [--dir &lt;path&gt;]</span></span>
<span class="line"><span>  [--slug &lt;slug&gt;] [--team &lt;id&gt;]</span></span></code></pre></div><p><code>&lt;connection&gt;</code> is the basename under <code>bot/mcp-connections/</code> or <code>bot/host-connections/</code>. A <code>url</code> connection with <code>oauth: true</code> opens a browser PKCE flow and saves tokens bound to that URL, so authorize again after you change it. A <code>cursorAccount</code> connection exits nonzero and points to the cursor.com dashboard. See <a href="./../guides/mcp-oauth.html">Host MCP OAuth</a>.</p><h2 id="channel-helpers" tabindex="-1">Channel helpers <a class="header-anchor" href="#channel-helpers" aria-label="Permalink to &quot;Channel helpers&quot;">​</a></h2><h3 id="slack" tabindex="-1">Configure Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Configure Slack {#slack}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk slack setup</span></span>
<span class="line"><span>agent-sdk slack create [--dir &lt;path&gt;] [--name &lt;name&gt;] [--env prod]</span></span>
<span class="line"><span>  [--slack-team &lt;id&gt;] [--team &lt;id&gt;] [--icon &lt;url-or-file&gt;]</span></span>
<span class="line"><span>  [--prefix &lt;prefix&gt; | --no-prefix] [--channel-posts] [--json]</span></span>
<span class="line"><span>agent-sdk slack destroy [--dir &lt;path&gt;] [--env prod] [--yes] [--dry-run]</span></span>
<span class="line"><span>  [--slack-team &lt;id&gt;] [--team &lt;id&gt;] [--json]</span></span>
<span class="line"><span>agent-sdk slack icon &lt;url-or-file&gt; [--dir &lt;path&gt;] [--env prod]</span></span>
<span class="line"><span>  [--slack-team &lt;id&gt;] [--team &lt;id&gt;] [--json]</span></span>
<span class="line"><span>agent-sdk slack init --manual [--dir &lt;path&gt;] [--name &lt;name&gt;]</span></span>
<span class="line"><span>  [--prefix &lt;prefix&gt; | --no-prefix] [--channel-posts]</span></span>
<span class="line"><span>  [--install | --no-install] [--slack-team &lt;id&gt;] [--env dev|prod]</span></span>
<span class="line"><span>agent-sdk slack manifest [--dir &lt;path&gt;] [--name &lt;name&gt;]</span></span>
<span class="line"><span>  [--env dev|prod|both] [--channel-posts] [--dry-run]</span></span>
<span class="line"><span>agent-sdk slack doctor [--dir &lt;path&gt;]</span></span>
<span class="line"><span>  [--prefix &lt;prefix&gt; | --no-prefix] [--channel &lt;id&gt;]... [--json]</span></span></code></pre></div><p><code>slack create</code> opens the <a href="https://cursor.com/dashboard/deployed-agents" target="_blank" rel="noreferrer">Deployed Agents</a> wizard, writes the token pair to <code>.env.local</code>, and runs <code>doctor</code>, which checks both tokens and Socket Mode. It makes the development app unless you pass <code>--env prod</code>. The token prefix defaults to the project directory name in upper snake case. <code>--channel-posts</code> adds the message events that <code>engagement.channelPosts</code> needs. See <a href="./../guides/slack.html">Slack</a> for manual setup.</p><h3 id="github" tabindex="-1">Test GitHub webhooks <a class="header-anchor" href="#github" aria-label="Permalink to &quot;Test GitHub webhooks {#github}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk github forward [--dir &lt;path&gt;] [--slug &lt;slug&gt;] [--channel &lt;id&gt;]</span></span>
<span class="line"><span>  [--repo owner/repo | --org &lt;org&gt;] [--events a,b,c]</span></span>
<span class="line"><span>  [--url &lt;url&gt;] [--host &lt;host&gt;] [--port &lt;n&gt;]</span></span>
<span class="line"><span>  [--secret &lt;secret&gt;] [--install]</span></span>
<span class="line"><span>agent-sdk github replay &lt;pr-url-or-owner/repo#N&gt;</span></span>
<span class="line"><span>  [--events a,b,c | &#39;*&#39;] [--action &lt;action&gt;] [--conclusion &lt;result&gt;]</span></span>
<span class="line"><span>  [--comment &lt;body&gt;] [--context &lt;name&gt;] [--dir &lt;path&gt;]</span></span>
<span class="line"><span>  [--slug &lt;slug&gt;] [--channel &lt;id&gt;] [--url &lt;url&gt;]</span></span>
<span class="line"><span>  [--secret &lt;secret&gt;] [--dry-run] [--fixtures-dir &lt;dir&gt;] [--json]</span></span>
<span class="line"><span>agent-sdk github events [--dir &lt;path&gt;] [--host &lt;host&gt;] [--port &lt;n&gt;] [--json]</span></span>
<span class="line"><span>agent-sdk github doctor [--install] [--json]</span></span></code></pre></div><p><code>forward</code> sends live deliveries to discovered channels through <code>gh webhook forward</code>. It needs repository admin access, or organization owner access for <code>--org</code>, and it uses the GitHub CLI&#39;s own login, so unset <code>GITHUB_TOKEN</code> and <code>GH_TOKEN</code> first. <code>doctor</code> checks the GitHub CLI and its webhook extension.</p><p><code>replay</code> reads a pull request with read access, builds webhook payloads, and posts them to matching channels. Its events are <code>pull_request</code>, the default, <code>issue_comment</code>, <code>pull_request_review_comment</code>, <code>check_run</code>, <code>check_suite</code>, <code>workflow_run</code>, and <code>status</code>. <code>--dry-run</code> prints the payloads without posting, and <code>--fixtures-dir</code> also writes them as fixtures. See <a href="./../guides/github.html">GitHub</a> for channel setup.</p><h3 id="replay-other-webhooks" tabindex="-1">Test GitLab, Bitbucket, and PagerDuty webhooks <a class="header-anchor" href="#replay-other-webhooks" aria-label="Permalink to &quot;Test GitLab, Bitbucket, and PagerDuty webhooks {#replay-other-webhooks}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk gitlab replay &lt;mr-url-or-group/project!N&gt; [replay flags]</span></span>
<span class="line"><span>agent-sdk bitbucket replay &lt;pr-url-or-workspace/repo#N&gt; [replay flags]</span></span>
<span class="line"><span>agent-sdk pagerduty replay [incident-id] [replay flags]</span></span>
<span class="line"><span>agent-sdk &lt;gitlab|bitbucket|pagerduty&gt; events [--dir &lt;path&gt;] [--json]</span></span>
<span class="line"><span>agent-sdk &lt;gitlab|bitbucket&gt; forward [--dir &lt;path&gt;]</span></span></code></pre></div><p>Replay takes the same flags as <code>github replay</code>, including <code>--fixtures-dir</code>. <code>events</code> lists the discovered channels, and <code>forward</code> prints the webhook and tunnel recipe for live deliveries.</p><table tabindex="0"><thead><tr><th>Command</th><th>Replay events</th><th>Default event</th><th>Read credential</th><th><code>--secret</code> default</th></tr></thead><tbody><tr><td><code>gitlab replay</code></td><td><code>merge_request</code>, <code>note</code>, <code>pipeline</code>, <code>push</code></td><td><code>merge_request</code></td><td><code>GITLAB_TOKEN</code></td><td><code>GITLAB_WEBHOOK_SECRET</code></td></tr><tr><td><code>bitbucket replay</code></td><td><code>pullrequest:created</code>, <code>pullrequest:updated</code>, <code>pullrequest:comment_created</code>, <code>repo:push</code>, in Cloud or Data Center format</td><td><code>pullrequest:created</code></td><td><code>BITBUCKET_TOKEN</code></td><td><code>BITBUCKET_WEBHOOK_SECRET</code></td></tr><tr><td><code>pagerduty replay</code></td><td><code>incident.triggered</code>, <code>.acknowledged</code>, <code>.annotated</code>, <code>.escalated</code>, <code>.resolved</code>, <code>.reopened</code></td><td><code>incident.triggered</code></td><td>None</td><td><code>PAGERDUTY_WEBHOOK_SECRET</code></td></tr></tbody></table><p>PagerDuty replay&#39;s incident ID defaults to <code>PREPLAY1</code>, and <code>--comment</code> is the note body for <code>annotated</code>. Without a secret, its deliveries are unsigned, and <code>agent-sdk dev</code> admits them from loopback. See <a href="./../guides/gitlab.html">GitLab</a>, <a href="./../guides/bitbucket.html">Bitbucket</a>, and <a href="./../guides/pagerduty.html">PagerDuty</a> for channel setup.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables {#environment-variables}&quot;">​</a></h2><p>The CLI tries <code>--api-key</code>, <code>CURSOR_API_KEY</code>, <code>CURSOR_API_KEY_FILE</code>, <code>CURSOR_SERVICE_ACCOUNT_KEY</code>, then the stored <code>agent-sdk login</code> credential, in that order.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Contract</th></tr></thead><tbody><tr><td><code>CURSOR_API_KEY</code></td><td>Cursor credential.</td></tr><tr><td><code>CURSOR_API_KEY_FILE</code></td><td>Path to a Cursor credential file.</td></tr><tr><td><code>CURSOR_SERVICE_ACCOUNT_KEY</code></td><td>Team service-account credential.</td></tr><tr><td><code>CURSOR_API_BASE_URL</code></td><td>Backend for login, account, deployment, and event commands.</td></tr><tr><td><code>CURSOR_BACKEND_URL</code></td><td>Backend for agent turns. Set it with <code>CURSOR_API_BASE_URL</code> for a non-default backend.</td></tr><tr><td><code>AGENT_SERVE_CONFIG_DIR</code></td><td>CLI config directory for stored credentials and update state.</td></tr><tr><td><code>AGENT_SERVE_NO_UPDATE_CHECK</code>, <code>NO_UPDATE_NOTIFIER</code>, <code>CI</code></td><td>Turn off update checks when set to a value other than <code>0</code>.</td></tr><tr><td><code>GITHUB_WEBHOOK_SECRET</code></td><td>Default secret for GitHub forwarding and replay.</td></tr><tr><td><code>GITHUB_APP_ID</code>, <code>GITHUB_APP_PRIVATE_KEY</code>, <code>GITHUB_APP_INSTALLATION_ID</code></td><td>GitHub App credentials for outbound API calls.</td></tr><tr><td><code>GITHUB_TOKEN</code>, <code>GH_TOKEN</code></td><td>Tokens for outbound GitHub calls.</td></tr><tr><td><code>GITLAB_TOKEN</code>, <code>GITLAB_WEBHOOK_SECRET</code></td><td>GitLab API token and default webhook token.</td></tr><tr><td><code>GITLAB_API_BASE_URL</code></td><td>GitLab REST base URL for self-managed hosts.</td></tr><tr><td><code>BITBUCKET_TOKEN</code>, <code>BITBUCKET_WEBHOOK_SECRET</code></td><td>Bitbucket API token and default signing secret.</td></tr><tr><td><code>BITBUCKET_API_BASE_URL</code></td><td>Bitbucket Data Center REST base URL.</td></tr><tr><td><code>SLACK_BOT_TOKEN</code>, <code>SLACK_APP_TOKEN</code></td><td>Slack tokens for one agent. Multi-agent servers use <code>&lt;PREFIX&gt;_SLACK_BOT_TOKEN</code> and <code>&lt;PREFIX&gt;_SLACK_APP_TOKEN</code>.</td></tr></tbody></table><h2 id="exit-status" tabindex="-1">Exit status <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status&quot;">​</a></h2><p>Every command uses these exit codes, and <code>agent-sdk help --json</code> lists them as <code>exitCodes</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td><code>ok</code></td></tr><tr><td><code>1</code></td><td><code>failed</code>, <code>aborted</code>, <code>invalid_argument</code>, <code>rate_limited</code>, or <code>unavailable</code></td></tr><tr><td><code>2</code></td><td><code>usage</code>, for a bad command, flag, or argument</td></tr><tr><td><code>3</code></td><td><code>pending</code>, while the work still runs</td></tr><tr><td><code>4</code></td><td><code>not_found</code></td></tr><tr><td><code>5</code></td><td><code>unauthenticated</code> or <code>permission_denied</code></td></tr><tr><td><code>6</code></td><td><code>conflict</code> or <code>failed_precondition</code></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./project-layout.html">Project layout</a></li><li><a href="./sessions.html">Sessions, events, and streaming</a></li><li><a href="./../deployment.html">Deployment</a></li><li><a href="./../guides/migrate.html">Early-alpha migration</a></li></ul>`,143)])])}const u=t(n,[["render",d]]);export{g as __pageData,u as default};
